from collections import deque

def bfs_at_depth(graph, start, target_depth):
    # BFS to find nodes at exactly target_depth
    # Returns nodes at exactly that depth (not including start or intermediate)

    visited = set([start])
    queue = deque([(start, 0)])  # (node, depth)
    nodes_at_target_depth = []

    while queue:
        node, depth = queue.popleft()

        if depth == target_depth:
            nodes_at_target_depth.append(node)
            continue  # Don't explore further from target depth

        if depth < target_depth and node in graph:
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, depth + 1))

    return nodes_at_target_depth

# Find nodes at depth 3
start_node = "fc9b003bb0"
depth_3_nodes = bfs_at_depth(graph, start_node, 3)

print(f"Nodes at depth 3 from {start_node}:")
print(depth_3_nodes)
print(f"\nTotal nodes at depth 3: {len(depth_3_nodes)}")

# Let's trace the BFS levels for verification
def trace_bfs(graph, start, max_depth):
    levels = {0: [start]}
    visited = set([start])

    for depth in range(max_depth):
        next_level = []
        for node in levels[depth]:
            if node in graph:
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        next_level.append(neighbor)
        levels[depth + 1] = next_level

    return levels

levels = trace_bfs(graph, start_node, 3)
for d in range(4):
    print(f"Depth {d}: {levels[d]}")
